    def begin(self):
        """Start a transaction. Transactions nest: each begin() pushes a new
        layer, and commit()/rollback() act on the innermost one."""
        self._layers.append({})

    def in_transaction(self):
        return bool(self._layers)

    def commit(self):
        """Commit the innermost transaction, folding its writes into the
        enclosing layer (or into ``_base`` when it is the outermost layer).
        Writes made in the inner transaction override the parent's state for
        the same key."""
        if not self._layers:
            raise RuntimeError("no transaction to commit")
        layer = self._layers.pop()
        if self._layers:
            parent = self._layers[-1]
            for k, v in layer.items():
                parent[k] = v
        else:
            for k, v in layer.items():
                if v is _TOMBSTONE:
                    self._base.pop(k, None)
                else:
                    self._base[k] = v

    def rollback(self):
        """Discard only the innermost open transaction's writes."""
        if not self._layers:
            raise RuntimeError("no transaction to rollback")
        self._layers.pop()"}

